#include <cstdio>
#include <cstring>
#include <iostream>
#include <algorithm>

using namespace std;

const int N = 101;
int n, k;
int a[N];
int zl[N];
bool have[N];
int tot = 0, ans = 0;
int p[N], f;

void pd()
{
    for (int i = 1; i <= zl[0]; i++) {
        if (p[zl[i]] == 0) {
            f = zl[i];
            return;
        }
    }
}

int main()
{
    memset(have, 0, sizeof(have));
    scanf("%d%d", &n, &k);

    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        p[a[i]]++;
        if (p[a[i]] == 1) {
            zl[++zl[0]] = a[i];
        }
    }

    for (int i = 1; i <= n; i++) {
        if (!have[a[i]] && tot < k) {
            ans++;
            tot++;
            have[a[i]] = true;
        } else if (have[a[i]]) {
            continue;
        } else {
            have[a[i]] = true;
            ans++;

            int r = i + 1;
            memset(p, 0, sizeof(p));

            while (p[0] < k && r <= n) {
                if (p[a[r]] == 0 && have[a[r]]) {
                    p[a[r]] = 1;
                    p[0]++;
                    f = a[r];
                }
                r++;
            }

            pd();
            have[f] = false;
        }
    }

    printf("%d", ans);
    return 0;
}

#include <cstdio>
#include <vector>
#include <queue>
#include <algorithm>
#include <utility>

using namespace std;

int main() {
    int n, k;
    scanf("%d%d", &n, &k);

    vector<int> a(n), values;
    for (int &x : a) {
        scanf("%d", &x);
        values.push_back(x);
    }

    sort(values.begin(), values.end());
    values.erase(unique(values.begin(), values.end()), values.end());

    int m = values.size();
    for (int &x : a)
        x = lower_bound(values.begin(), values.end(), x) - values.begin();

    vector<int> nextUse(n), last(m, n + 1);
    for (int i = n - 1; i >= 0; --i) {
        nextUse[i] = last[a[i]];
        last[a[i]] = i;
    }

    vector<bool> have(m, false);
    vector<int> currentNext(m, n + 1);
    priority_queue<pair<int, int>> pq;

    int total = 0;
    int answer = 0;

    for (int i = 0; i < n; ++i) {
        int book = a[i];

        if (!have[book]) {
            ++answer;

            if (k == 0)
                continue;

            if (total == k) {
                while (!have[pq.top().second] ||
                       currentNext[pq.top().second] != pq.top().first)
                    pq.pop();

                int removed = pq.top().second;
                pq.pop();
                have[removed] = false;
                --total;
            }

            have[book] = true;
            ++total;
        }

        currentNext[book] = nextUse[i];
        pq.push({nextUse[i], book});
    }

    printf("%d", answer);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<int> a(n), nextUse(n);
    unordered_map<int, int> last;

    for (int& x : a) cin >> x;

    for (int i = n - 1; i >= 0; --i) {
        auto it = last.find(a[i]);
        nextUse[i] = (it == last.end() ? n : it->second);
        last[a[i]] = i;
    }

    if (k == 0) {
        cout << n;
        return 0;
    }

    unordered_set<int> have;
    unordered_map<int, int> currentNext;
    priority_queue<pair<int, int>> pq;

    int ans = 0;

    for (int i = 0; i < n; ++i) {
        int book = a[i];

        if (!have.count(book)) {
            ++ans;

            if (static_cast<int>(have.size()) == k) {
                while (!pq.empty()) {
                    auto [pos, candidate] = pq.top();
                    if (have.count(candidate) &&
                        currentNext[candidate] == pos) {
                        break;
                    }
                    pq.pop();
                }

                int removed = pq.top().second;
                pq.pop();
                have.erase(removed);
                currentNext.erase(removed);
            }

            have.insert(book);
        }

        currentNext[book] = nextUse[i];
        pq.push({nextUse[i], book});
    }

    cout << ans;
    return 0;
}

